begin;
with j as (select * from jsonb_to_recordset($law7d0020$[{"code_id":"GK_RF","article_number":"123.8","version_date":"1994-11-30","article_text":"1. Ассоциацией (союзом) признается объединение юридических лиц и (или) граждан, основанное на добровольном или в установленных законом случаях на обязательном членстве и созданное для представления и защиты общих, в том числе профессиональных, интересов, для достижения общественно полезных целей, а также иных не противоречащих закону и имеющих некоммерческий характер целей.\n\nВ организационно-правовой форме ассоциации (союза) создаются, в частности, объединения лиц, имеющие целями координацию их предпринимательской деятельности, представление и защиту общих имущественных интересов, профессиональные объединения граждан, не имеющие целью защиту трудовых прав и интересов своих членов, профессиональные объединения граждан, не связанные с их участием в трудовых отношениях (объединения оценщиков, лиц творческих профессий и другие), саморегулируемые организации и их объединения. (В редакции федеральных законов от 13.07.2015 № 268-ФЗ; от 07.02.2017 № 12-ФЗ)\n\n2. Ассоциации (союзы) могут иметь гражданские права и нести гражданские обязанности, соответствующие целям их создания и деятельности, предусмотренным уставами таких ассоциаций (союзов).\n\n3. Ассоциация (союз) является собственником своего имущества. Ассоциация (союз) отвечает по своим обязательствам всем своим имуществом, если иное не предусмотрено законом в отношении ассоциаций (союзов) отдельных видов.\n\nАссоциация (союз) не отвечает по обязательствам своих членов, если иное не предусмотрено законом.\n\nЧлены ассоциации (союза) не отвечают по ее обязательствам, за исключением случаев, если законом или уставом ассоциации (союза) предусмотрена субсидиарная ответственность ее членов.","article_title":"Статья 123.8. Основные положения об ассоциации (союзе)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e9b437a6d1200e00fadae2fef8a85b1a891b6d07ea23a00902b482a80ccae9c4"},{"code_id":"GK_RF","article_number":"123.9","version_date":"1994-11-30","article_text":"1. Число учредителей ассоциации (союза) не может быть менее двух. Законами, устанавливающими особенности правового положения ассоциаций (союзов) отдельных видов, могут быть установлены иные требования к минимальному числу учредителей таких ассоциаций (союзов).\n\n2. Устав ассоциации (союза) должен содержать сведения о ее наименовании и месте нахождения, предмете и целях ее деятельности, условия о порядке вступления (принятия) членов в ассоциацию (союз) и выхода из нее, сведения о составе и компетенции органов ассоциации (союза) и порядке принятия ими решений, в том числе по вопросам, решения по которым принимаются единогласно или квалифицированным большинством голосов, об имущественных правах и обязанностях членов ассоциации (союза), о порядке распределения имущества, оставшегося после ликвидации ассоциации (союза).","article_title":"Статья 123.9. Учредители ассоциации (союза) и устав ассоциации (союза)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69a86466e20766a0d7239685f3eeb17070a7463bb7394ac7a3c2a232b24a2adc"},{"code_id":"GK_RF","article_number":"124","version_date":"1994-11-30","article_text":"1. Российская Федерация, субъекты Российской Федерации: республики, края, области, города федерального значения, автономная область, автономные округа, а также городские, сельские поселения и другие муниципальные образования выступают в отношениях, регулируемых гражданским законодательством, на равных началах с иными участниками этих отношений - гражданами и юридическими лицами.\n\n2. К субъектам гражданского права, указанным в пункте 1 настоящей статьи, применяются нормы, определяющие участие юридических лиц в отношениях, регулируемых гражданским законодательством, если иное не вытекает из закона или особенностей данных субъектов.","article_title":"Статья 124. Российская Федерация, субъекты Российской Федерации, муниципальные образования - субъекты гражданского права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"823a4d4c4f3fee89f2c404a281b68ee3dad50cb3511890bc4f85444bd985a2f1"},{"code_id":"GK_RF","article_number":"125","version_date":"1994-11-30","article_text":"1. От имени Российской Федерации и субъектов Российской Федерации могут своими действиями приобретать и осуществлять имущественные и личные неимущественные права и обязанности, выступать в суде органы государственной власти в рамках их компетенции, установленной актами, определяющими статус этих органов.\n\n2. От имени муниципальных образований своими действиями могут приобретать и осуществлять права и обязанности, указанные в пункте 1 настоящей статьи, органы местного самоуправления в рамках их компетенции, установленной актами, определяющими статус этих органов.\n\n3. В случаях и в порядке, предусмотренных федеральными законами, указами Президента Российской Федерации и постановлениями Правительства Российской Федерации, нормативными актами субъектов Российской Федерации и муниципальных образований, по их специальному поручению от их имени могут выступать государственные органы, органы местного самоуправления, а также юридические лица и граждане.","article_title":"Статья 125. Порядок участия Российской Федерации, субъектов Российской Федерации, муниципальных образований в отношениях, регулируемых гражданским законодательством","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6122095a7af4384fee5d05ce627782a8473449f7f9503da39a0aebfa58c8852d"},{"code_id":"GK_RF","article_number":"126","version_date":"1994-11-30","article_text":"1. Российская Федерация, субъект Российской Федерации, муниципальное образование отвечают по своим обязательствам принадлежащим им на праве собственности имуществом, кроме имущества, которое закреплено за созданными ими юридическими лицами на праве хозяйственного ведения или оперативного управления, а также имущества, которое может находиться только в государственной или муниципальной собственности.\n\nОбращение взыскания на землю и другие природные ресурсы, находящиеся в государственной или муниципальной собственности, допускается в случаях, предусмотренных законом.\n\n2. Юридические лица, созданные Российской Федерацией, субъектами Российской Федерации, муниципальными образованиями, не отвечают по их обязательствам.\n\n3. Российская Федерация, субъекты Российской Федерации, муниципальные образования не отвечают по обязательствам созданных ими юридических лиц, кроме случаев, предусмотренных законом.\n\n4. Российская Федерация не отвечает по обязательствам субъектов Российской Федерации и муниципальных образований.\n\n5. Субъекты Российской Федерации, муниципальные образования не отвечают по обязательствам друг друга, а также по обязательствам Российской Федерации.\n\n6. Правила пунктов 2 - 5 настоящей статьи не распространяются на случаи, когда Российская Федерация приняла на себя гарантию (поручительство) по обязательствам субъекта Российской Федерации, муниципального образования или юридического лица либо указанные субъекты приняли на себя гарантию (поручительство) по обязательствам Российской Федерации.","article_title":"Статья 126. Ответственность по обязательствам Российской Федерации, субъекта Российской Федерации, муниципального образования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e30a58ae70e0e9978ebf9cc3bc7ff2f322e94dcf163846ec1a89f417188fcb3"},{"code_id":"GK_RF","article_number":"127","version_date":"1994-11-30","article_text":"Особенности ответственности Российской Федерации и субъектов Российской Федерации в отношениях, регулируемых гражданским законодательством, с участием иностранных юридических лиц, граждан и государств определяются законом об иммунитете государства и его собственности.","article_title":"Статья 127. Особенности ответственности Российской Федерации и субъектов Российской Федерации в отношениях, регулируемых гражданским законодательством, с участием иностранных юридических лиц, граждан и государств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8ade5c7296aa7501134bbc2382af6b45b3052f134e29f6f9a6f09c5364578ea9"},{"code_id":"GK_RF","article_number":"128","version_date":"1994-11-30","article_text":"К объектам гражданских прав относятся вещи (включая наличные деньги и документарные ценные бумаги), иное имущество, в том числе имущественные права (включая безналичные денежные средства, в том числе цифровые рубли, бездокументарные ценные бумаги, цифровые права); результаты работ и оказание услуг; охраняемые результаты интеллектуальной деятельности и приравненные к ним средства индивидуализации (интеллектуальная собственность); нематериальные блага. (В редакции  федеральных законов от 18.03.2019 № 34-ФЗ, от 24.07.2023 № 339-ФЗ)\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 128. Объекты гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"be8f4ce6bfb94027177018bfe5d8d60416b73d301afbc6ef3154d771fe86c126"},{"code_id":"GK_RF","article_number":"13","version_date":"1994-11-30","article_text":"Ненормативный акт государственного органа или органа местного самоуправления, а в случаях, предусмотренных законом, также нормативный акт, не соответствующие закону или иным правовым актам и нарушающие гражданские права и охраняемые законом интересы гражданина или юридического лица, могут быть признаны судом недействительными.\n\nВ случае признания судом акта недействительным нарушенное право подлежит восстановлению либо защите иными способами, предусмотренными статьей 12 настоящего Кодекса.","article_title":"Статья 13. Признание недействительным акта государственного органа или органа местного самоуправления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44948e57e29c13246c406a0e3ef5ab98c9f0916dd1767ebfdf3f006600d2f276"},{"code_id":"GK_RF","article_number":"130","version_date":"1994-11-30","article_text":"К недвижимым вещам относятся также подлежащие государственной регистрации воздушные и морские суда, суда внутреннего плавания. Законом к недвижимым вещам может быть отнесено и иное имущество. (В редакции Федерального закона от 13.07.2015 № 216-ФЗ)\n\nК недвижимым вещам относятся жилые и нежилые помещения, а также предназначенные для размещения транспортных средств части зданий или сооружений (маши\n\nно-места), если границы таких помещений, частей зданий или сооружений описаны в установленном законодательством о государственном кадастровом учете порядке. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 315-ФЗ)","article_title":"Статья 130. Недвижимые и движимые вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d92b31c62ad8dda9d5a00ff683ee86462a9a5029180b8b0d0f82a7f33575522"},{"code_id":"GK_RF","article_number":"131","version_date":"1994-11-30","article_text":"Информация предоставляется в любом органе, осуществляющем регистрацию недвижимости, независимо от места совершения регистрации.","article_title":"Статья 131. Государственная регистрация недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d63586028a8b316fb71345f9cba616e031d2d4363fcabc793e5956c774cd3924"},{"code_id":"GK_RF","article_number":"132","version_date":"1994-11-30","article_text":"1. Предприятием как объектом прав признается имущественный комплекс, используемый для осуществления предпринимательской деятельности.\n\nПредприятие в целом как имущественный комплекс признается недвижимостью.\n\n2. Предприятие в целом или его часть могут быть объектом купли-продажи, залога, аренды и других сделок, связанных с установлением, изменением и прекращением вещных прав.\n\nВ состав предприятия как имущественного комплекса входят все виды имущества, предназначенные для его деятельности, включая земельные участки, здания, сооружения, оборудование, инвентарь, сырье, продукцию, права требования, долги, а также права на обозначения, индивидуализирующие предприятие, его продукцию, работы и услуги (коммерческое обозначение, товарные знаки, знаки обслуживания), и другие исключительные права, если иное не предусмотрено законом или договором. (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)","article_title":"Статья 132. Предприятие","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5539f7f2ad6f43061ec669318e08d405ac8d5da8d3c32d10c132f4235fb93d0d"},{"code_id":"GK_RF","article_number":"133","version_date":"1994-11-30","article_text":"1. Вещь, раздел которой в натуре невозможен без разрушения, повреждения вещи или изменения ее назначения и которая выступает в обороте как единый объект вещных прав, является неделимой вещью и в том случае, если она имеет составные части.\n\n2. Замена одних составных частей неделимой вещи другими составными частями не влечет возникновения иной вещи, если при этом существенные свойства вещи сохраняются.\n\n3. Взыскание может быть обращено на неделимую вещь только в целом, если законом или судебным актом не установлена возможность выделения из вещи ее составной части, в том числе в целях продажи ее отдельно.\n\n4. Отношения по поводу долей в праве собственности на неделимую вещь регулируются правилами главы 16, статьи 1168 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 133. Неделимые вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40d994b6ddf70af782eb99feee5d6bdf55edc7ac7d1324ab857112f3e5ddbcff"},{"code_id":"GK_RF","article_number":"133.1","version_date":"1994-11-30","article_text":"Недвижимой вещью, участвующей в обороте как единый объект, может являться единый недвижимый комплекс - совокупность объединенных единым назначением зданий, сооружений и иных вещей, неразрывно связанных физически или технологически, в том числе линейных объектов (железные дороги, линии электропередачи, трубопроводы и другие), либо расположенных на одном земельном участке, если в едином государственном реестре прав на недвижимое имущество зарегистрировано право собственности на совокупность указанных объектов в целом как одну недвижимую вещь.\n\nК единым недвижимым комплексам применяются правила о неделимых вещах.\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 142-ФЗ)","article_title":"Статья 133.1. Единый недвижимый комплекс","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04cd42cd450adc220c4d5d0058bf54d250d81901648f4c3c161c0b5ef54e21ad"},{"code_id":"GK_RF","article_number":"134","version_date":"1994-11-30","article_text":"Если различные вещи соединены таким образом, который предполагает их использование по общему назначению (сложная вещь), то действие сделки, совершенной по поводу сложной вещи, распространяется на все входящие в нее вещи, поскольку условиями сделки не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 134. Сложные вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"282f6bcee635957b1d351fe75bcc2aaec749e2f117611481d5a762b55fc27d28"},{"code_id":"GK_RF","article_number":"135","version_date":"1994-11-30","article_text":"Вещь, предназначенная для обслуживания другой, главной, вещи и связанная с ней общим назначением (принадлежность), следует судьбе главной вещи, если договором не предусмотрено иное.","article_title":"Статья 135. Главная вещь и принадлежность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c17a0cdc97eefcdf6f6d85773eab4af87c0fa9f0a2485f8f2f91ba528c50df7"},{"code_id":"GK_RF","article_number":"136","version_date":"1994-11-30","article_text":"Плоды, продукция, доходы, полученные в результате использования вещи, независимо от того, кто использует такую вещь, принадлежат собственнику вещи, если иное не предусмотрено законом, иными правовыми актами, договором или не вытекает из существа отношений.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 136. Плоды, продукция и доходы","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b48e1990980fcb9ff983fc0b3f02f2db6bfb311cf74d4c43814c01e51c867cd"},{"code_id":"GK_RF","article_number":"137","version_date":"1994-11-30","article_text":"К животным применяются общие правила об имуществе постольку, поскольку законом или иными правовыми актами не установлено иное.\n\nПри осуществлении прав не допускается жестокое обращение с животными, противоречащее принципам гуманности.","article_title":"Статья 137. Животные","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4dc12fd3d9418fd95b231a375b8e8d36c3df7fcbe3c2979b4cc3c21af7900907"},{"code_id":"GK_RF","article_number":"138","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 18.12.2006 № 231-ФЗ)","article_title":"Статья 138. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45740e332c27a9cd0706f6f2abe7683e9b043ff9593181185e457091501a104d"},{"code_id":"GK_RF","article_number":"139","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 18.12.2006 № 231-ФЗ)","article_title":"Статья 139. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"45740e332c27a9cd0706f6f2abe7683e9b043ff9593181185e457091501a104d"},{"code_id":"GK_RF","article_number":"14","version_date":"1994-11-30","article_text":"Допускается самозащита гражданских прав.\n\nСпособы самозащиты должны быть соразмерны нарушению и не выходить за пределы действий, необходимых для его пресечения.","article_title":"Статья 14. Самозащита гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f8743447a19ba75dbb9fda10a1ff3e930a1a8f8cbee6a5593b4833dede5d39eb"},{"code_id":"GK_RF","article_number":"140","version_date":"1994-11-30","article_text":"1. Рубль является законным платежным средством, обязательным к приему по нарицательной стоимости на всей территории Российской Федерации.\n\nПлатежи на территории Российской Федерации осуществляются путем наличных и безналичных расчетов, включая расчеты цифровыми рублями. (В редакции  Федерального закона от 24.07.2023 № 339-ФЗ)\n\n2. Случаи, порядок и условия использования иностранной валюты на территории Российской Федерации определяются законом или в установленном им порядке.","article_title":"Статья 140. Деньги (валюта)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb7f0979a7ee583dce391341c61d3c3e084c9b0b029c43ca67fc5083243bb5d7"},{"code_id":"GK_RF","article_number":"141","version_date":"1994-11-30","article_text":"Виды имущества, признаваемого валютными ценностями, и порядок совершения сделок с ними определяются законом о валютном регулировании и валютном контроле.\n\nПрава на валютные ценности защищаются в Российской Федерации на общих основаниях. (В редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 141. Валютные ценности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89ecc0d90e218a655d42e6ff3aef788335587c2cd4aa75a367546f383d8eac55"},{"code_id":"GK_RF","article_number":"141.1","version_date":"1994-11-30","article_text":"1. Цифровыми правами признаются названные в таком качестве в законе обязательственные и иные права, содержание и условия осуществления которых определяются в соответствии с правилами информационной системы, отвечающей установленным законом признакам. Осуществление, распоряжение, в том числе передача, залог, обременение цифрового права другими способами или ограничение распоряжения цифровым правом возможны только в информационной системе без обращения к третьему лицу.\n\n2. Если иное не предусмотрено законом, обладателем цифрового права признается лицо, которое в соответствии с правилами информационной системы имеет возможность распоряжаться этим правом. В случаях и по основаниям, которые предусмотрены законом, обладателем цифрового права признается иное лицо.\n\n3. Переход цифрового права на основании сделки не требует согласия лица, обязанного по такому цифровому праву.\n\n(Дополнение статьей - Федеральный закон от 18.03.2019 № 34-ФЗ)\n\n(Дополнение главой - Федеральный закон от 21.12.2021 № 430-ФЗ)","article_title":"Статья 141.1. Цифровые права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef0a3749a75d719fdf6f213c185c575f05f33d42b28f09b5eacd9029a9787d9f"},{"code_id":"GK_RF","article_number":"141.2","version_date":"1994-11-30","article_text":"1. Земельным участком признается часть поверхности земли, границы которой определены в порядке, установленном законом.\n\n2. Земельный участок является недвижимой вещью (статья 130).","article_title":"Статья 141.2. Земельный участок как недвижимая вещь","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8154d8e8d0f1524599d5e4cc227725d109c466b12acf3e46581818c4d6d9ea9d"},{"code_id":"GK_RF","article_number":"141.3","version_date":"1994-11-30","article_text":"1. Здания и сооружения являются недвижимыми вещами (статья 130). Здания и сооружения создаются в результате строительства.\n\n2. Здания и сооружения могут быть образованы в результате раздела недвижимой вещи (здания, сооружения, единого недвижимого комплекса) или в результате объединения нескольких недвижимых вещей (зданий, сооружений, всех помещений и машино-мест, расположенных в одном здании, сооружении).\n\n3. Изменение характеристик здания или сооружения не влечет образования новых здания или сооружения, если иное не установлено законом.","article_title":"Статья 141.3. Здания и сооружения как недвижимые вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0189cd1a73827ba3fc96440def20ae322c9844aa4a54b93573a5539b4b50e604"},{"code_id":"GK_RF","article_number":"141.4","version_date":"1994-11-30","article_text":"1. Помещением признается обособленная часть здания или сооружения, пригодная для постоянного проживания граждан (жилое помещение) либо для других целей, не связанных с проживанием граждан (нежилое помещение), и подходящая для использования в соответствующих целях.\n\n2. Помещения, предназначенные для обслуживания иных помещений в здании или сооружении, являются общим имуществом в таких здании или сооружении и не участвуют в обороте как самостоятельные недвижимые вещи, за исключением случая, предусмотренного пунктом 7 статьи 2875 настоящего Кодекса.\n\n3. Помещения, машино-места как недвижимые вещи могут быть образованы в том числе в результате раздела недвижимой вещи (здания, сооружения, в которых они образуются, помещения), объединения смежных недвижимых вещей (помещений, машино-мест) либо в результате реконструкции здания, сооружения, при проведении которой образуются помещения, машино-места как новые недвижимые вещи.\n\n4. В одном здании, сооружении может быть образовано не менее двух помещений и (или) машино-мест.\n\n5. При перепланировке помещений, машино-мест могут быть образованы иные помещения, машино-места путем объединения смежных помещений, машино-мест или раздела помещений, машино-мест. В остальных случаях осуществления перепланировки помещение, машино-место сохраняются как недвижимая вещь, в том числе в измененных границах.\n\n6. Образование помещений и машино-мест в объектах незавершенного строительства не допускается.\n\n7. Правила настоящей главы о помещениях подлежат применению к жилым помещениям, если иное не установлено Жилищным кодексом Российской Федерации.","article_title":"Статья 141.4. Помещения как недвижимые вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"643d2f9fca1706d6f9e8f9de9a9995dc6a93c19c1fc27e6766438de6c057c349"},{"code_id":"GK_RF","article_number":"141.5","version_date":"1994-11-30","article_text":"1. Законом могут быть установлены запреты или ограничения на образование отдельных видов недвижимых вещей либо условия, при соблюдении которых допускается образование таких недвижимых вещей.\n\n2. Обременения, установленные в отношении исходной недвижимой вещи, сохраняются в отношении всех образованных недвижимых вещей, если настоящим Кодексом или соглашением собственника исходной недвижимой вещи с лицом, в пользу которого установлено обременение, не определено иное.\n\n3. При разделе линейного объекта, в том числе при осуществлении которого не производится его реконструкция, могут быть образованы один или несколько линейных объектов, включая линейный объект, раздел которого осуществлен, с измененными параметрами.\n\n(Глава в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 141.5. Образование недвижимых вещей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a8d4facea3c573789034ba7786e4b27bea3f4a12bc89d2cbfa5559ce16ec0f5"},{"code_id":"GK_RF","article_number":"142","version_date":"1994-11-30","article_text":"1. Ценными бумагами являются документы, соответствующие установленным законом требованиям и удостоверяющие обязательственные и иные права, осуществление или передача которых возможны только при предъявлении таких документов (документарные ценные бумаги).\n\nЦенными бумагами признаются также обязательственные и иные права, которые закреплены в решении о выпуске или ином акте лица, выпустившего ценные бумаги в соответствии с требованиями закона, и осуществление и передача которых возможны только с соблюдением правил учета этих прав в соответствии со статьей 149 настоящего Кодекса (бездокументарные ценные бумаги).\n\n2. Ценными бумагами являются акция, вексель, закладная, инвестиционный пай паевого инвестиционного фонда, коносамент, облигация, чек и иные ценные бумаги, названные в таком качестве в законе или признанные таковыми в установленном законом порядке.\n\nВыпуск или выдача ценных бумаг подлежит государственной регистрации в случаях, установленных законом.","article_title":"Статья 142. Ценные бумаги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a12c60fd613dabfa809e0b8a8089ac94c9d42b9f7ec3d6196b6b11980bca26b1"},{"code_id":"GK_RF","article_number":"143","version_date":"1994-11-30","article_text":"1. Документарные ценные бумаги могут быть предъявительскими (ценными бумагами на предъявителя), ордерными и именными.\n\n2. Предъявительской является документарная ценная бумага, по которой лицом, уполномоченным требовать исполнения по ней, признается ее владелец.\n\n3. Ордерной является документарная ценная бумага, по которой лицом, уполномоченным требовать исполнения по ней, признается ее владелец, если ценная бумага выдана на его имя или перешла к нему от первоначального владельца по непрерывному ряду индоссаментов.\n\n4. Именной является документарная ценная бумага, по которой лицом, уполномоченным требовать исполнения по ней, признается одно из следующих указанных лиц:\n\n1) владелец ценной бумаги, указанный в качестве правообладателя в учетных записях, которые ведутся обязанным лицом или действующим по его поручению и имеющим соответствующую лицензию лицом. Законом может быть предусмотрена обязанность передачи такого учета лицу, имеющему соответствующую лицензию;\n\n2) владелец ценной бумаги, если ценная бумага была выдана на его имя или перешла к нему от первоначального владельца в порядке непрерывного ряда уступок требования (цессий) путем совершения на ней именных передаточных надписей или в иной форме в соответствии с правилами, установленными для уступки требования (цессии).\n\n5. Выпуск или выдача предъявительских ценных бумаг допускается в случаях, установленных законом.\n\nВозможность выпуска или выдачи определенных документарных ценных бумаг в качестве именных либо ордерных может быть исключена законом.\n\n6. Если иное не установлено настоящим Кодексом, законом или не вытекает из особенностей фиксации прав на бездокументарные ценные бумаги, к таким ценным бумагам применяются правила об именных документарных ценных бумагах, правообладатель которых определяется в соответствии с учетными записями.","article_title":"Статья 143. Виды ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26daeea7a3f0c3b483b2d7afe5f6cadfeabdd214db9d81257ef4caf37adb5456"},{"code_id":"GK_RF","article_number":"143.1","version_date":"1994-11-30","article_text":"1. Обязательные реквизиты, требования к форме документарной ценной бумаги и другие требования к документарной ценной бумаге определяются законом или в установленном им порядке.\n\n2. При отсутствии в документе обязательных реквизитов документарной ценной бумаги, несоответствии его установленной форме и другим требованиям документ не является ценной бумагой, но сохраняет значение письменного доказательства.","article_title":"Статья 143.1. Требования к документарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"209c3b2d12bd5b073798969e9ea244181ef1b17236d615c40f7a3fccefe4b450"},{"code_id":"GK_RF","article_number":"144","version_date":"1994-11-30","article_text":"1. Надлежащим исполнением по документарной ценной бумаге признается исполнение лицу, определенному пунктами 2 - 4 статьи 143 настоящего Кодекса (владельцу ценной бумаги).\n\n2. Если ответственное за исполнение по документарной ценной бумаге лицо знало, что владелец ценной бумаги, которому произведено исполнение, не является надлежащим обладателем права на ценную бумагу, оно обязано возместить убытки, причиненные обладателю права на ценную бумагу.","article_title":"Статья 144. Исполнение по документарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4fb7a8adc4514a73b47253c5afb644fcd01b23b85b83153a9f943892d43f5a95"},{"code_id":"GK_RF","article_number":"145","version_date":"1994-11-30","article_text":"1. Лицо, ответственное за исполнение по документарной ценной бумаге, вправе выдвигать против требований владельца ценной бумаги только те возражения, которые вытекают из ценной бумаги или основаны на отношениях между этими лицами.\n\nЛицо, составившее документарную ценную бумагу, отвечает по ценной бумаге и в случае, если документ поступил в обращение помимо его воли.\n\nПредусмотренные настоящим пунктом правила об ограничении возражений не применяются в случае, если владелец ценной бумаги в момент ее приобретения знал или должен был знать об отсутствии основания возникновения прав, удостоверенных ценной бумагой, в том числе о недействительности такого основания, либо об отсутствии прав предшествующих владельцев ценной бумаги, в том числе о недействительности основания их возникновения, а также в случае, если владелец ценной бумаги не является ее добросовестным приобретателем (статья 1471).\n\n2. Лица, ответственные за исполнение по ордерной ценной бумаге, не вправе ссылаться на возражения других лиц, ответственных за исполнение по данной ценной бумаге.\n\n3. Против требования об исполнении по документарной ценной бумаге лицо, указанное в качестве ответственного за исполнение по ней, может выдвинуть возражения, связанные с подделкой такой ценной бумаги или с оспариванием факта подписания им ценной бумаги (подлог ценной бумаги).","article_title":"Статья 145. Возражения по документарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7997f663b08ef56ea54f67aa7b9f362de8396c8a8ce9a9f7affbff5d1d6f56dd"},{"code_id":"GK_RF","article_number":"146","version_date":"1994-11-30","article_text":"1. С переходом права на документарную ценную бумагу переходят все удостоверенные ею права в совокупности.\n\n2. Права, удостоверенные предъявительской ценной бумагой, передаются приобретателю путем вручения ему ценной бумаги лицом, совершившим ее отчуждение.\n\nПрава, удостоверенные предъявительской ценной бумагой, могут перейти к другому лицу независимо от ее вручения в случаях и по основаниям, которые установлены законом.\n\n3. Права, удостоверенные ордерной ценной бумагой, передаются приобретателю путем ее вручения с совершением на ней передаточной надписи - индоссамента. Если иное не предусмотрено настоящим Кодексом или законом, к передаче ордерных ценных бумаг применяются установленные законом о переводном и простом векселе правила о передаче векселя.\n\n4. Права, удостоверенные именной документарной ценной бумагой, передаются приобретателю путем вручения ему ценной бумаги лицом, совершающим ее отчуждение, с совершением на ней именной передаточной надписи или в иной форме в соответствии с правилами, установленными для уступки требования (цессии).\n\nНормы параграфа 1 главы 24 настоящего Кодекса применяются к передаче прав, удостоверенных именными документарными ценными бумагами, в порядке уступки требования (цессии), если иное не установлено правилами настоящей главы, иным законом или не вытекает из существа соответствующей ценной бумаги.\n\n5. В случае неисполнения обязательства передать ордерную или именную документарную ценную бумагу приобретатель вправе требовать ее изъятия у лица, во владении которого она находится, за исключением случаев, если на ценной бумаге учинены индоссамент или передаточная надпись лица, совершившего отчуждение, по которым права переданы иному лицу.\n\n6. В случае неисполнения обязательства по совершению индоссамента или передаточной надписи на ордерной или именной документарной ценной бумаге переход прав на ордерную или именную документарную ценную бумагу осуществляется по требованию приобретателя на основании решения суда путем совершения лицом, осуществляющим исполнение судебного решения, надписи на ценной бумаге, которая имеет силу индоссамента или передаточной надписи.\n\n7. Переход прав, удостоверенных ордерной или именной ценной бумагой, к другому лицу по основаниям иным, чем передача по договору, осуществляется путем приобретения права на ценную бумагу в случаях и по основаниям, которые установлены законом.\n\n8. Переход прав\n\nна ордерные или именные ценные бумаги подтверждается:\n\n1) при наследовании - отметкой нотариуса на самой ценной бумаге, которая имеет силу индоссамента или передаточной надписи предшествующего правообладателя;\n\n2) при реализации таких ценных бумаг в случае обращения на них взыскания - отметкой лица, уполномоченного на реализацию имущества владельца таких ценных бумаг;\n\n3) в иных случаях - на основании решения суда отметкой лица, осуществляющего исполнение судебного решения.\n\n9. При учете прав на именную документарную ценную бумагу права переходят к лицу, указанному в ценной бумаге, в момент внесения в учетные записи отметки о переходе прав. Отметка вносится на основании передаточного акта, совершенного сторонами в присутствии лица, осуществляющего учет в соответствии с пунктом 4 статьи 143 настоящего Кодекса, или на основании нотариально удостоверенного передаточного акта, предъявленного лицу, осуществляющему учет, одной из сторон.\n\n10. При уклонении лица, осуществляющего учет в соответствии с пунктом 4 статьи 143 настоящего Кодекса, от внесения в учетные записи отметки о переходе прав лицо, на имя которого совершен передаточный акт, может требовать в судебном порядке внесения соответствующей отметки в учетные записи.","article_title":"Статья 146. Переход прав, удостоверенных документарными ценными бумагами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5bcc4be638cf306716ad0fa789fb3b7d6fc76361430cf07b4c92df2fad15b7ed"},{"code_id":"GK_RF","article_number":"147","version_date":"1994-11-30","article_text":"1. Лицо, передавшее документарную ценную бумагу, несет ответственность за недействительность прав, удостоверенных ценной бумагой, если иное не установлено законом.\n\nЛицо, передавшее документарную ценную бумагу, несет ответственность за исполнение обязательства по ней при наличии соответствующей оговорки, а также в иных случаях, установленных законом.\n\n2. Владелец ценной бумаги, обнаруживший ее подлог или подделку, вправе потребовать от лица, передавшего ему ценную бумагу, исполнения обязательств по такой ценной бумаге и возмещения убытков.","article_title":"Статья 147. Ответственность за действительность прав, удостоверенных документарной ценной бумагой","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"60a32533857150e7d2cc963c7e92c0dad01eb18f412ed9f2a342e06777b25766"},{"code_id":"GK_RF","article_number":"147.1","version_date":"1994-11-30","article_text":"1. Истребование документарных ценных бумаг из чужого незаконного владения осуществляется по правилам настоящего Кодекса об истребовании вещи из чужого незаконного владения с особенностями, предусмотренными настоящей статьей.\n\n2. Правом на истребование документарных ценных бумаг из чужого незаконного владения обладает лицо, которое на момент, когда ценные бумаги выбыли из его владения, являлось их законным владельцем.\n\n3. Не могут быть истребованы от добросовестного приобретателя предъявительские ценные бумаги независимо от того, какое право они удостоверяют, а также ордерные и именные ценные бумаги, удостоверяющие денежное требование.\n\n4. Правообладатель ценной бумаги, утративший ее в результате неправомерных действий, вправе потребовать от лица, которое приобрело ее у третьего лица, независимо от того, является ли такое третье лицо добросовестным или недобросовестным приобретателем, либо признается законным владельцем, возврата ценной бумаги или возмещения ее рыночной стоимости, если указанный приобретатель, от которого истребуется ценная бумага, своими обманными или другими незаконными действиями способствовал утрате прав законного владельца на ценную бумагу либо в качестве предшествующего владельца знал или должен был знать о наличии прав иных лиц на ценную бумагу.\n\n5. Лицо, которому документарная ценная бумага была возвращена из чужого незаконного владения, вправе потребовать от недобросовестного владельца возврата всего полученного по ценной бумаге, а также возмещения убытков; от добросовестного владельца - возврата всего полученного по ценной бумаге со времени, когда он узнал или должен был узнать о неправомерности владения ею либо получил из суда уведомление о предъявлении к нему иска об истребовании ценной бумаги.\n\nЕсли незаконный владелец воспользовался предоставленным ценной бумагой преимущественным правом приобретения какого-либо имущества, лицо, которому документарная ценная бумага была возвращена из чужого незаконного владения, вправе потребовать от такого владельца передачи ему приобретенного имущества при условии возмещения его стоимости по цене приобретения указанного имущества незаконным владельцем, а от недобросовестного владельца вправе потребовать также возмещения убытков.","article_title":"Статья 147.1. Особенности истребования документарных ценных бумаг от добросовестного приобретателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40f6741ac03ff40fe40469dfc8c1c5b5ebf59c9cc9568ace4bb63c17d7976747"},{"code_id":"GK_RF","article_number":"148","version_date":"1994-11-30","article_text":"1. Восстановление прав по утраченной ценной бумаге на предъявителя производится судом в порядке вызывного производства в соответствии с процессуальным законодательством по заявлению лица, утратившего ценную бумагу, о признании ее недействительной и восстановлении прав по ценной бумаге.\n\n2. Лицо, утратившее ордерную ценную бумагу, вправе заявить в письменной форме об этом всем обязанным по ней лицам с указанием причин утраты.\n\nОбязанное лицо, получившее заявление лица, утратившего ордерную ценную бумагу, в случае предъявления ее иным лицом должно приостановить исполнение предъявителю ценной бумаги и сообщить ему о притязаниях заявителя, а также сообщить заявителю о лице, предъявившем ценную бумагу. Если в течение трех месяцев со дня заявления лица об утрате ордерной ценной бумаги лицо, утратившее ценную бумагу, не обратилось в суд с соответствующим требованием к предъявителю ценной бумаги, обязанное лицо должно произвести исполнение предъявителю ценной бумаги. Если спор между лицом, утратившим ценную бумагу, и лицом, предъявившим ценную бумагу, разрешен судом, исполнение производится лицу, в пользу которого принято судебное решение.\n\nПри отсутствии спора о праве на ордерную ценную бумагу лицо, утратившее ее, вправе потребовать в судебном порядке исполнения от обязанного лица.\n\n3. Восстановление прав по утраченной именной документарной ценной бумаге производится судом в порядке особого производства по делам об установлении фактов, имеющих юридическое значение, в соответствии с процессуальным законодательством по заявлению лица, утратившего такую ценную бумагу, а в случаях, предусмотренных законом, также иных лиц.\n\n4. При утрате учетных записей о владельцах именных документарных ценных бумаг лицо, ведущее учет, обязано опубликовать незамедлительно информацию об этом в средствах массовой информации, в которых подлежат опубликованию сведения о банкротстве, и предложить лицам, которые были указаны в качестве правообладателей в учетных записях, представить именные ценные бумаги в срок, который указан при опубликовании информации и который не может быть менее трех месяцев с момента ее опубликования.\n\nУчетные записи о владельцах именных документарных ценных бумаг должны быть восстановлены лицом, ведущим такой учет, в течение месяца со дня окончания срока представления ценных бумаг их владельцами.\n\nПри уклонении лица, ведущего учет, от восстановления учетных записей они подлежат восстановлению судом по иску заинтересованного лица в порядке, установленном процессуальным законодательством.\n\n5. Лицо, обязанное по именной документарной ценной бумаге, и лицо, осуществляющее по его поручению учет прав на ценные бумаги, несут солидарную ответственность за убытки, причиненные владельцам таких ценных бумаг в результате утраты учетных записей или нарушения порядка и сроков восстановления таких записей, если не докажут, что утрата или нарушение имели место вследствие непреодолимой силы.","article_title":"Статья 148. Восстановление прав по документарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0fb6ee2348f57653404ec4b1af94419c4ff77887385da623871446a12618ac5f"},{"code_id":"GK_RF","article_number":"148.1","version_date":"1994-11-30","article_text":"В соответствии с законом или в установленном им порядке документарные ценные бумаги могут быть обездвижены, то есть переданы на хранение лицу, которое в соответствии с законом вправе осуществлять хранение документарных ценных бумаг и (или) учет прав на ценные бумаги. Переход прав на обездвиженные ценные бумаги и осуществление прав, удостоверенных такими ценными бумагами, регулируются статьями 149 - 1495 настоящего Кодекса, если иное не предусмотрено законом.","article_title":"Статья 148.1. Обездвижение документарных ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43484011cc978591eb0bcdaaab4e956c75c25771a69310bcf00bd135f51a4a29"},{"code_id":"GK_RF","article_number":"149","version_date":"1994-11-30","article_text":"1. Лицами, ответственными за исполнение по бездокументарной ценной бумаге, являются лицо, которое выпустило ценную бумагу, а также лица, которые предоставили обеспечение исполнения соответствующего обязательства. Лица, ответственные за исполнение по бездокументарной ценной бумаге, должны быть указаны в решении о ее выпуске или в ином предусмотренном законом акте лица, выпустившего ценную бумагу.\n\nПраво требовать от обязанного лица исполнения по бездокументарной ценной бумаге признается за лицом, указанным в учетных записях в качестве правообладателя, или за иным лицом, которое в соответствии с законом осуществляет права по ценной бумаге.\n\n2. Учет прав на бездокументарные ценные бумаги осуществляется путем внесения записей по счетам лицом, действующим по поручению лица, обязанного по ценной бумаге, либо лицом, действующим на основании договора с правообладателем или с иным лицом, которое в соответствии с законом осуществляет права по ценной бумаге. Ведение записей по учету таких прав осуществляется лицом, имеющим предусмотренную законом лицензию.\n\n3. Распоряжение, в том числе передача, залог, обременение другими способами бездокументарных ценных бумаг, а также ограничения распоряжения ими могут осуществляться только посредством обращения к лицу, осуществляющему учет прав на бездокументарные ценные бумаги, для внесения соответствующих записей.\n\n4. Лицо, выпустившее бездокументарную ценную бумагу, и лицо, осуществляющее по его поручению учет прав на такие ценные бумаги, несут солидарную ответственность за убытки, причиненные в результате нарушения порядка учета прав, порядка совершения операций по счетам, утраты учетных данных, предоставления недостоверной информации об учетных данных, если не докажут, что нарушение имело место вследствие непреодолимой силы.\n\nЛицо, ответственное за исполнение по бездокументарной ценной бумаге, не несет ответственность за убытки, причиненные в результате нарушения порядка учета прав лицами, действующими на основании договора с правообладателем или с иным лицом, которое в соответствии с законом осуществляет права по ценной бумаге.","article_title":"Статья 149. Общие положения о бездокументарных ценных бумагах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ec2b74930e2c886d032ca3ac08716d8599885a8d7d306ceb84850943b26800ae"},{"code_id":"GK_RF","article_number":"149.1","version_date":"1994-11-30","article_text":"1. Надлежащим исполнением по бездокументарной ценной бумаге признается исполнение, произведенное обязанным лицом лицам, указанным в абзаце втором пункта 1 статьи 149 настоящего Кодекса.\n\nЗаконом могут быть установлены случаи, когда на определенную дату фиксируется перечень лиц, имеющих право требовать исполнения по бездокументарным ценным бумагам. Надлежащим признается исполнение, произведенное таким лицам.\n\n2. В случаях, предусмотренных законом, надлежащим признается исполнение лицам иным, чем те, которые указаны в пункте 1 настоящей статьи.\n\n3. Правила, предусмотренные пунктом 2 статьи 144 и статьей 145 настоящего Кодекса, применяются к отношениям, связанным с исполнением по бездокументарным ценным бумагам, если это не противоречит существу таких ценных бумаг.","article_title":"Статья 149.1. Исполнение по бездокументарной ценной бумаге","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f899df6911da457ab6dbcee96d134c0089a3d6e350e79a8d01e4e8b1aa3e50a4"},{"code_id":"GK_RF","article_number":"149.2","version_date":"1994-11-30","article_text":"1. Передача прав на бездокументарные ценные бумаги приобретателю осуществляется посредством списания бездокументарных ценных бумаг со счета лица, совершившего их отчуждение, и зачисления их на счет приобретателя на основании распоряжения лица, совершившего отчуждение. Законом или договором правообладателя с лицом, осуществляющим учет прав на бездокументарные ценные бумаги, могут быть предусмотрены иные основания и условия списания ценных бумаг и их зачисления, в том числе возможность списания ценных бумаг со счета лица, совершившего отчуждение, без представления его распоряжения.\n\n2. Права по бездокументарной ценной бумаге переходят к приобретателю с момента внесения лицом, осуществляющим учет прав на бездокументарные ценные бумаги, соответствующей записи по счету приобретателя.\n\n3. Залог, обременение другими способами бездокументарных ценных бумаг, а также ограничения распоряжения ими возникают после внесения лицом, осуществляющим учет прав, соответствующей записи о залоге, обременении или ограничении по счету правообладателя либо в установленных законом случаях по счету иного лица.\n\nОбременение бездокументарных ценных бумаг может также возникать с момента их зачисления на счет, на котором в соответствии с законом учитываются права на обремененные бездокументарные ценные бумаги.\n\nВнесение записей о залоге или об ином обременении бездокументарных ценных бумаг производится на основании распоряжения правообладателя (залоговое распоряжение и т.п.), если иное не предусмотрено законом. Записи об изменении условий обременения и о его прекращении вносятся на основании распоряжения правообладателя при наличии согласия в письменной форме лица, в пользу которого установлено обременение, либо без такого распоряжения в случаях, предусмотренных законом или соглашением правообладателя с лицом, осуществляющим учет прав на бездокументарные ценные бумаги, и лицом, в пользу которого установлено обременение.\n\n4. При уклонении лица, совершившего отчуждение, либо лица, предоставляющего ценные бумаги в обеспечение исполнения обязательства, от представления лицу, осуществляющему учет прав на бездокументарные ценные бумаги, распоряжения о проведении операции по счету приобретатель или лицо, в пользу которого устанавливается обременение бездокументарных ценных бумаг, вправе требовать в судебном порядке внесения записей о переходе прав на ценные бумаги или об их обременении на условиях, предусмотренных договором с лицом, совершающим отчуждение, или с лицом, предоставляющим ценные бумаги в обеспечение исполнения обязательства.\n\nПри наличии нескольких лиц, в пользу которых установлено обязательство по передаче либо обременению прав на одни и те же бездокументарные ценные бумаги, в случае, если операция по их передаче или по обременению еще не осуществлена, преимущество имеет лицо, в пользу которого обязательство возникло ранее, а если это невозможно установить - лицо, первым предъявившее иск.\n\n5. Оформление перехода прав на бездокументарные ценные бумаги в порядке наследования производится на основании представленного наследником свидетельства о праве на наследство (статья 1162).\n\nПереход прав на бездокументарные ценные бумаги при реализации таких ценных бумаг в случае обращения на них взыскания оформляется на основании распоряжения лица, уполномоченного на реализацию имущества правообладателя.\n\nОформление передачи прав на бездокументарные ценные бумаги в соответствии с судебным решением производится лицом, осуществляющим учет прав, на основании решения суда или на основании акта лица, осуществляющего исполнение судебного решения.\n\n6. Уклонение или отказ лица, осуществляющего учет прав на бездокументарные ценные бумаги, от проведения операции по счету могут быть оспорены в суде.","article_title":"Статья 149.2. Переход прав по бездокументарной ценной бумаге и возникновение обременения бездокументарной ценной бумаги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f1e90b42f1e3d55e5de7ab9ec532675d8bce3fa50c78b6643c3d45ddeac149f"},{"code_id":"GK_RF","article_number":"149.3","version_date":"1994-11-30","article_text":"1. Правообладатель, со счета которого были неправомерно списаны бездокументарные ценные бумаги, вправе требовать от лица, на счет которого ценные бумаги были зачислены, возврата такого же количества соответствующих ценных бумаг.\n\nБездокументарные ценные бумаги, удостоверяющие только денежное право требования, а также бездокументарные ценные бумаги, приобретенные на организованных торгах, независимо от вида удостоверяемого права не могут быть истребованы от добросовестного приобретателя.\n\nЕсли бездокументарные ценные бумаги были безвозмездно приобретены у лица, которое не имело права их отчуждать, правообладатель вправе истребовать такие ценные бумаги во всех случаях.\n\n2. Если бездокументарные ценные бумаги, которые правообладатель вправе истребовать, были конвертированы в другие ценные бумаги, правообладатель вправе истребовать те ценные бумаги, в которые были конвертированы ценные бумаги, списанные с его счета.\n\n3. Правообладатель, со счета которого бездокументарные ценные бумаги были неправомерно списаны, при наличии возможности приобретения таких же ценных бумаг на организованных торгах по своему выбору вправе потребовать от лиц, несущих перед ним ответственность за причиненные этим убытки, приобретения таких же ценных бумаг за их счет либо возмещения всех необходимых для их приобретения расходов.","article_title":"Статья 149.3. Защита нарушенных прав правообладателей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e20387b22f463460919a462611e4416d8b8fa99318ecd73094bc3caa09f48f4f"},{"code_id":"GK_RF","article_number":"149.4","version_date":"1994-11-30","article_text":"1. В случае удовлетворения требования правообладателя о возврате бездокументарных ценных бумаг в соответствии с пунктом 1 или пунктом 2 статьи 1493 настоящего Кодекса правообладатель пользуется в отношении лица, со счета которого ценные бумаги были ему возвращены, правами, указанными в пункте 5 статьи 1471 настоящего Кодекса.\n\n2. В случае реализации неуправомоченными лицами удостоверенных бездокументарными ценными бумагами права на участие в управлении акционерным обществом или иного права на участие в принятии решения собрания правообладатель может оспорить соответствующее решение собрания, нарушающее его права и охраняемые законом интересы, если акционерное общество или лица, волеизъявление которых имело значение при принятии решения собрания, знали или должны были знать о наличии спора о правах на бездокументарные ценные бумаги и голосование правообладателя могло повлиять на принятие решения.\n\nИск об оспаривании решения собрания может быть предъявлен в течение трех месяцев со дня, когда лицо, имеющее право на ценную бумагу, узнало или должно было узнать о неправомерном списании ценных бумаг с его счета, но не позднее одного года со дня принятия соответствующего решения.\n\nСуд может оставить решение собрания в силе, если признание решения недействительным повлечет причинение несоразмерного ущерба кредиторам акционерного общества или иным третьим лицам.","article_title":"Статья 149.4. Последствия истребования бездокументарных ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c17d30276919b4756f43e2693bd72bf07a92de020956d9d0c136194c9a03f352"},{"code_id":"GK_RF","article_number":"149.5","version_date":"1994-11-30","article_text":"1. При утрате учетных записей, удостоверяющих права на бездокументарные ценные бумаги, лицо, осуществляющее учет прав, обязано незамедлительно опубликовать информацию об этом в средствах массовой информации, в которых подлежат опубликованию сведения о банкротстве, и обратиться в суд с заявлением о восстановлении данных учета прав в порядке, установленном процессуальным законодательством.\n\nТребование о восстановлении данных учета прав на бездокументарные ценные бумаги может быть заявлено любым заинтересованным лицом. Восстановление данных учета прав осуществляется в порядке, установленном процессуальным законодательством. При восстановлении данных учета прав на бездокументарные ценные бумаги записи о правообладателях вносятся на основании решения суда.\n\nИнформация о восстановлении данных учета прав на бездокументарные ценные бумаги опубликовывается для всеобщего сведения в средствах массовой информации, в которых подлежат опубликованию сведения о банкротстве, на основании решения суда за счет лица, осуществлявшего этот учет на момент утраты учетных записей, удостоверявших права на бездокументарные ценные бумаги.\n\n2. Записи об учете прав на бездокументарные ценные бумаги не имеют силы с момента, когда лицо, осуществляющее учет прав, утратило учетные записи, и до дня вступления в законную силу решения суда о восстановлении данных учета прав.","article_title":"Статья 149.5. Последствия утраты учетных записей, удостоверяющих права на бездокументарные ценные бумаги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6f7be78a10b70bfa9d2d7c9f94a676a8ab48ad60abc4f30636c6b4068ec7bf6"},{"code_id":"GK_RF","article_number":"15","version_date":"1994-11-30","article_text":"1. Лицо, право которого нарушено, может требовать полного возмещения причиненных ему убытков, если законом или договором не предусмотрено возмещение убытков в меньшем размере.\n\n2. Под убытками понимаются расходы, которые лицо, чье право нарушено, произвело или должно будет произвести для восстановления нарушенного права, утрата или повреждение его имущества (реальный ущерб), а также неполученные доходы, которые это лицо получило бы при обычных условиях гражданского оборота, если бы его право не было нарушено (упущенная выгода).\n\nЕсли лицо, нарушившее право, получило вследствие этого доходы, лицо, право которого нарушено, вправе требовать возмещения наряду с другими убытками упущенной выгоды в размере не меньшем, чем такие доходы.","article_title":"Статья 15. Возмещение убытков","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fa0ed33016de2dca4ef3b2ebc462e99e9c1377fdfc9f10c3296bdf565989edd2"},{"code_id":"GK_RF","article_number":"150","version_date":"1994-11-30","article_text":"1. Жизнь и здоровье, достоинство личности, личная неприкосновенность, честь и доброе имя, деловая репутация, неприкосновенность частной жизни, неприкосновенность жилища, личная и семейная тайна, свобода передвижения, свобода выбора места пребывания и жительства, имя гражданина, авторство, иные нематериальные блага, принадлежащие гражданину от рождения или в силу закона, неотчуждаемы и непередаваемы иным способом.\n\n2. Нематериальные блага защищаются в соответствии с настоящим Кодек\n\nсом и другими законами в случаях и в порядке, ими предусмотренных, а также в тех случаях и пределах, в каких использование способов защиты гражданских прав (статья 12) вытекает из существа нарушенного нематериального блага или личного неимущественного права и характера последствий этого нарушения.\n\nВ случаях, если того требуют интересы гражданина, принадлежащие ему нематериальные блага могут быть защищены, в частности, путем признания судом факта нарушения его личного неимущественного права, опубликования решения суда о допущенном нарушении, а также путем пресечения или запрещения действий, нарушающих или создающих угрозу нарушения личного неимущественного права либо посягающих или создающих угрозу посягательства на нематериальное благо.\n\nВ случаях и в порядке, которые предусмотрены законом, нематериальные блага, принадлежавшие умершему, могут защищаться другими лицами.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 150. Нематериальные блага","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6f0de3b5a028c408a76436211a03babf585e114b7eea107de3445203d258bd4"},{"code_id":"GK_RF","article_number":"151","version_date":"1994-11-30","article_text":"Если гражданину причинен моральный вред (физические или нравственные страдания) действиями, нарушающими его личные неимущественные права либо посягающими на принадлежащие гражданину нематериальные блага, а также в других случаях, предусмотренных законом, суд может возложить на нарушителя обязанность денежной компенсации указанного вреда. (В редакции Федерального закона от 02.07.2013 № 142-ФЗ)\n\nПри определении размеров компенсации морального вреда суд принимает во внимание степень вины нарушителя и иные заслуживающие внимания обстоятельства. Суд должен также учитывать степень физических и нравственных страданий, связанных с индивидуальными особенностями гражданина, которому причинен вред. (В редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 151. Компенсация морального вреда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"daccc1852096e061043ac5adb42e3e02cfa24d42510ed673f3fcd2134d5ded0b"},{"code_id":"GK_RF","article_number":"152","version_date":"1994-11-30","article_text":"1. Гражданин вправе требовать по суду опровержения порочащих его честь, достоинство или деловую репутацию сведений, если распространивший такие сведения не докажет, что они соответствуют действительности. Опровержение должно быть сделано тем же способом, которым были распространены сведения о гражданине, или другим аналогичным способом.\n\nПо требованию заинтересованных лиц допускается защита чести, достоинства и деловой репутации гражданина и после его смерти.\n\n2. Сведения, порочащие честь, достоинство или деловую репутацию гражданина и распространенные в средствах массовой информации, должны быть опровергнуты в тех же средствах массовой информации. Гражданин, в отношении которого в средствах массовой информации распространены указанные сведения, имеет право потребовать наряду с опровержением также опубликования своего ответа в тех же средствах массовой информации.\n\n3. Если сведения, порочащие честь, достоинство или деловую репутацию гражданина, содержатся в документе, исходящем от организации, такой документ подлежит замене или отзыву.\n\n4. В случаях, когда сведения, порочащие честь, достоинство или деловую репутацию гражданина, стали широко известны и в связи с этим опровержение невозможно довести до всеобщего сведения, гражданин вправе требовать удаления соответствующей информации, а также пресечения или запрещения дальнейшего распространения указанных сведений путем изъятия и уничтожения без какой бы то ни было компенсации изготовленных в целях введения в гражданский оборот экземпляров материальных носителей, содержащих указанные сведения, если без уничтожения таких экземпляров материальных носителей удаление соответствующей информации невозможно.\n\n5. Если сведения, порочащие честь, достоинство или деловую репутацию гражданина, оказались после их распространения доступными в сети \"Интернет\", гражданин вправе требовать удаления соответствующей информации, а также опровержения указанных сведений способом, обеспечивающим доведение опровержения до пользователей сети \"Интернет\".\n\n6. Порядок опровержения сведений, порочащих честь, достоинство или деловую репутацию гражданина, в иных случаях, кроме указанных в пунктах 2 - 5 настоящей статьи, устанавливается судом.\n\n7. Применение к нарушителю мер ответственности за неисполнение судебного решения не освобождает его от обязанности совершить предусмотренное решением суда действие.\n\n8. Если установить лицо, распространившее сведения, порочащие честь, достоинство или деловую репутацию гражданина, невозможно, гражданин, в отношении которого такие сведения распространены, вправе обратиться в суд с заявлением о признании распространенных сведений не соответствующими действительности.\n\n9. Гражданин, в отношении которого распространены сведения, порочащие его честь, достоинство или деловую репутацию, наряду с опровержением таких сведений или опубликованием своего ответа вправе требовать возмещения убытков и компенсации морального вреда, причиненных распространением таких сведений.\n\n10. Правила пунктов 1 - 9 настоящей статьи, за исключением положений о компенсации морального вреда, могут быть применены судом также к случаям распространения любых не соответствующих действительности сведений о гражданине, если такой гражданин докажет несоответствие указанных сведений действительности. Срок исковой давности по требованиям, предъявляемым в связи с распространением указанных сведений в средствах массовой информации, составляет один год со дня опубликования таких сведений в соответствующих средствах массовой информации.\n\n11. Правила настоящей статьи о защите деловой репутации гражданина, за исключением положений о компенсации морального вреда, соответственно применяются к защите деловой репутации юридического лица.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 142-ФЗ)","article_title":"Статья 152. Защита чести, достоинства и деловой репутации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"95dd86cdf58fb186ef09e9d2dd5dbaad1c7ea09eb704036178a66beeab69cff8"},{"code_id":"GK_RF","article_number":"152.1","version_date":"1994-11-30","article_text":"1) использование изображения осуществляется в государственных, общественных или иных публичных интересах;\n\n2) изображение гражданина получено при съемке, которая проводится в местах, открытых для свободного посещения, или на публичных мероприятиях (собраниях, съездах, конференциях, концертах, представлениях, спортивных соревнованиях и подобных мероприятиях), за исключением случаев, когда такое изображение является основным объектом использования;\n\n3) гражданин позировал за плату.\n\n(Дополнение статьей - Федеральный закон от 18.12.2006 № 231-ФЗ)","article_title":"Статья 152.1. Охрана изображения гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"789d31efeafd7ed1927c17968d6e809e5c944232535b3e9f47ff916d4ecfde3c"},{"code_id":"GK_RF","article_number":"152.2","version_date":"1994-11-30","article_text":"1. Если иное прямо не предусмотрено законом, не допускаются без согласия гражданина сбор, хранение, распространение и использование любой информации о его частной жизни, в частности сведений о его происхождении, о месте его пребывания или жительства, о личной и семейной жизни.\n\nНе являются нарушением правил, установленных абзацем первым настоящего пункта, сбор, хранение, распространение и использование информации о частной жизни гражданина в государственных, общественных или иных публичных интересах, а также в случаях, если информация о частной жизни гражданина ранее стала общедоступной либо была раскрыта самим гражданином или по его воле.\n\n2. Стороны обязательства не вправе разглашать ставшую известной им при возникновении и (или) исполнении обязательства информацию о частной жизни гражданина, являющегося стороной или третьим лицом в данном обязательстве, если соглашением не предусмотрена возможность такого разглашения информации о сторонах.\n\n3. Неправомерным распространением полученной с нарушением закона информации о частной жизни гражданина считается, в частности, ее использование при создании произведений науки, литературы и искусства, если такое использование нарушает интересы гражданина.\n\n4. В случаях, когда информация о частной жизни гражданина, полученная с нарушением закона, содержится в документах, видеозаписях или на иных материальных носителях, гражданин вправе обратиться в суд с требованием об удалении соответствующей информации, а также о пресечении или запрещении дальнейшего ее распространения путем изъятия и уничтожения без какой бы то ни было компенсации изготовленных в целях введения в гражданский оборот экземпляров материальных носителей, содержащих соответствующую информацию, если без уничтожения таких экземпляров материальных носителей удаление соответствующей информации невозможно.\n\n5. Право требовать защиты частной жизни гражданина способами, предусмотренными пунктом 2 статьи 150 настоящего Кодекса и настоящей статьей, в случае его смерти имеют дети, родители и переживший супруг такого гражданина.\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 142-ФЗ)\n\n(Наименование в редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 152.2. Охрана частной жизни гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d897b28c78a48a6caf5e960a1b59509c47e88668ce4bb5a820f79f2ca227b9d"},{"code_id":"GK_RF","article_number":"153","version_date":"1994-11-30","article_text":"Сделками признаются действия граждан и юридических лиц, направленные на установление, изменение или прекращение гражданских прав и обязанностей.","article_title":"Статья 153. Понятие сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"121d8cc077d974019bab6bd7099539c81daa39651070d0247ab623b9350e978a"},{"code_id":"GK_RF","article_number":"154","version_date":"1994-11-30","article_text":"1. Сделки могут быть двух- или многосторонними (договоры) и односторонними.\n\n2. Односторонней считается сделка, для совершения которой в соответствии с законом, иными правовыми актами или соглашением сторон необходимо и достаточно выражения воли одной стороны.\n\n3. Для заключения договора необходимо выражение согласованной воли двух сторон (двусторонняя сделка) либо трех или более сторон (многосторонняя сделка).","article_title":"Статья 154. Договоры и односторонние сделки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44fed5f1381b7975dd9f59955e45bf7e4a0855fbd170c404f866a8edb7dd4110"},{"code_id":"GK_RF","article_number":"155","version_date":"1994-11-30","article_text":"Односторонняя сделка создает обязанности для лица, совершившего сделку. Она может создавать обязанности для других лиц лишь в случаях, установленных законом либо соглашением с этими лицами.","article_title":"Статья 155. Обязанности по односторонней сделке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e7b5d73e81b9088fe7b3fc69cd2db71f6fcf5cd29b92b1da31a44405b26c3a9"},{"code_id":"GK_RF","article_number":"156","version_date":"1994-11-30","article_text":"К односторонним сделкам соответственно применяются общие положения об обязательствах и о договорах, поскольку это не противоречит закону, одностороннему характеру и существу сделки. (В редакции Федерального закона от 07.05.2013 № 100-ФЗ)","article_title":"Статья 156. Правовое регулирование односторонних сделок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76eb3f3abcb69b1f71bb596d148f970159dab69589e604f9c0117af640ad49d3"}]$law7d0020$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
